MERGE INTO DPS2.REF_DEP_OPEN_BATCH_ERROR_CODE t USING (SELECT 'ROW_INVALID' C,'ردیف نامعتبر' F,'Invalid row' E,'VALIDATION' S,10 O FROM DUAL) s ON (t.ERROR_CODE=s.C)
